import XCTest
@testable import Markdown

class MarkdownTests: XCTestCase {
    
    override func setUp() {
        super.setUp()
        // Put setup code here. This method is called before the invocation of each test method in the class.
    }
    
    override func tearDown() {
        // Put teardown code here. This method is called after the invocation of each test method in the class.
        super.tearDown()
    }
    
    
    func testUnescapeAllEGrave() {
        
        var string = "Test for this \\[ blue string with &#x000C8;"
        string.unescapeAll()
        
        XCTAssert("Test for this [ blue string with È" == string)
    }
    
    func testUnescapeAllQuestionMark() {
        
        var string = "Test for this \\[ blue string with &#63;"
        string.unescapeAll()
        
        XCTAssert("Test for this [ blue string with ?" == string)
    }
    
    
    func testUnescapeAllCommercialAt() {
        
        var string = "Test for this \\[ blue string with &commat;"
        string.unescapeAll()
        
        XCTAssert("Test for this [ blue string with @" == string, "Error received: \(string)")
    }
    
    /// RESULT: PASS
    func testEscapeRe() {
        
        let string = "Test for this blue string with [.*]"
        let result = escapeRE(string)
        
        XCTAssert("Test for this blue string with \\[\\.\\*\\]" == result, "Error received: \(result)")
    }
    
    func testStringIndiceAccessPerformance() {
        // This is an example of a performance test case.
        self.measure {

            
            let string = ""
            

            for _ in 0 ..< 6000 {
                
                string.charAt(8000 - 1)
            }
        }
    }
    
    func testNSStringIndiceAccessPerformance() {
        // This is an example of a performance test case.
        self.measure {
            
            let nsstring =
            ""
            
            for _ in 0 ..< 6000 {
                
                nsstring.charAt(8000 - 1)
            }
            
        }
    }
    
}
